            lv_obj_set_style_pad_bottom(ui_Entry,0,LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_border_side(ui_Entry,LV_BORDER_SIDE_NONE,LV_PART_MAIN | LV_STATE_DEFAULT);
