            lv_obj_set_user_data(ui_Entry,(void *) p_cur_node);

            lv_obj_set_style_bg_color(ui_Entry,NAME_TEXT_BG_COLOR,LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_bg_opa(ui_Entry,LV_OPA_100,LV_PART_MAIN | LV_STATE_DEFAULT);

            lv_obj_set_style_text_color(ui_Entry,NAME_TEXT_COLOR,LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_text_opa(ui_Entry,LV_OPA_100,LV_PART_MAIN | LV_STATE_DEFAULT);

            lv_obj_set_style_text_color(ui_Entry,NAME_TEXT_COLOR_FOCUS,LV_PART_MAIN | LV_STATE_FOCUSED);
            lv_obj_set_style_bg_color(ui_Entry,NAME_TEXT_BG_COLOR_FOCUS,LV_PART_MAIN | LV_STATE_FOCUSED);

            ui_LabelEntry       = lv_label_create(ui_Entry);
            lv_obj_set_width(ui_LabelEntry,210);
            lv_obj_set_height(ui_LabelEntry,40);
