void ui_screen_phone_list_reset_create(ui_screen_phonebookfind_obj_t * p_screen_param)
{
    p_screen_param->p_start_node = get_phonebook_head_node();
    p_screen_param->p_end_node = get_phonebook_tail_node();
    p_screen_param->list_first_index = 0;
    p_screen_param->find_count = p_screen_param->phonebook_count;
    ui_screen_phone_list_create(p_screen_param,p_screen_param->obj_list,p_screen_param->p_start_node);

    uint32_t        per;

    per                 = 0;
    per                 = per * (100 - p_screen_param->bar_high) / 100;
    per                 = 100 - per;

    p_screen_param->bar_high = 3 * 100 / p_screen_param->find_count;

    if (p_screen_param->bar_high >= 100)
        p_screen_param->bar_high = 100;
    else if (p_screen_param->bar_high < 2)
        p_screen_param->bar_high = 2;

    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
    lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
    lv_obj_clear_flag(p_screen_param->bar,LV_OBJ_FLAG_HIDDEN);

    lv_obj_t *      get_first_obj = lv_obj_get_child(p_screen_param->obj_list,0);

    if (get_first_obj) {
        lv_obj_add_state(get_first_obj,LV_STATE_FOCUSED);
        }
}

void phonebookfind_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_phonebookfind_obj_t * p_screen_param;
    lv_obj_t *      list;
    uint32_t        child_cnt;
    uint32_t        child_id;
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;
    uint32_t        count;


    p_screen_param      = (ui_screen_phonebookfind_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (lv_obj_has_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN))
        list = p_screen_param->obj_list_find;
    else 
        list = p_screen_param->obj_list;

    if (list) {
        child_cnt           = lv_obj_get_child_cnt(list);
        child_id            = get_list_child_focused_id(list,child_cnt);
        }
    else {
        child_cnt           = 0;
        child_id            = 0;

        }

    __inf("phonebookfind_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);

    if (get_ime_pinyin_keyboard_active_state(p_screen_param->pinyin)) {
        ime_pinyin_ui_event_actions(key,p_screen_param->pinyin);

        label               = lv_textarea_get_label(p_screen_param->obj_textarea);
        count               = _lv_txt_get_encoded_length(lv_label_get_text(label));

        if (p_screen_param->wirte_count != count) {
            if (count != 0) {
#ifdef UI_DISPLAY_SPEED
                phonebook_find_list_by_text(ui_Screen,lv_label_get_text(label));

#else

                if (p_screen_param->obj_list_find) {
                    lv_obj_del(p_screen_param->obj_list_find);
                    p_screen_param->obj_list_find = NULL;
                    }

                p_screen_param->obj_list_find = phonebook_find_list_by_text(ui_Screen,p_screen_param->obj_list,
                    lv_label_get_text(label));
                lv_obj_add_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                }
            else {
#ifdef UI_DISPLAY_SPEED
                ui_screen_phone_list_reset_create(p_screen_param);

#else

                if (p_screen_param->obj_list_find) {
                    lv_obj_del(p_screen_param->obj_list_find);
                    p_screen_param->obj_list_find = NULL;
                    }

                lv_obj_clear_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                }

            p_screen_param->wirte_count = count;
            }
        }
    else {
        switch (key)
        {
#ifndef UI_DISPLAY_SPEED
            case LV_KEY_UP:
                {
                    if (child_cnt <= 1)
                        return;

                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(list,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                        get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                            }
                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(list,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                        get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }

                    label               = lv_obj_get_child(get_focus_obj,0);

                    app_fp_play_tts_menu(lv_label_get_text(label));
                    }
                break;

            case LV_KEY_DOWN:
                {
                    if (child_cnt <= 1)
                        return;

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(list,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                        get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(list,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                        get_focus_obj       = lv_obj_get_child(list,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }

                    label               = lv_obj_get_child(get_focus_obj,0);

                    app_fp_play_tts_menu(lv_label_get_text(label));
                    }
                break;

#else

            case LV_KEY_UP:
                {
                    if (child_cnt <= 1)
                        return;

                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    if (child_id != 0) {
                        get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                            }
                        }
                    else {
                        phonebook_map_node_t * p_cur_node;

                        get_focus_obj       = lv_obj_get_child(list,child_id);
                        p_cur_node          = lv_obj_get_user_data(get_focus_obj);

                        if (p_cur_node == get_phonebook_head_node_find(p_screen_param)) {
                            int             i   = 0;

                            p_cur_node          = get_phonebook_tail_node_find(p_screen_param);

                            for (i = 0; i < PHONE_LIST_COUNT - 1; i++) {
                                if (p_cur_node == get_phonebook_head_node_find(p_screen_param))
                                    break;

                                p_cur_node          = get_phonebook_prev_count_node(p_cur_node,1);

                                if (p_cur_node == NULL)
                                    break;
                                }

                            if (p_cur_node == NULL)
                                p_cur_node = get_phonebook_head_node_find(p_screen_param);

                            ui_screen_phone_list_create(p_screen_param,p_screen_param->obj_list,p_cur_node);

                            child_cnt           = lv_obj_get_child_cnt(list);

                            if (p_screen_param->find_count > child_cnt)
                                p_screen_param->list_first_index = p_screen_param->find_count - child_cnt;

                            pre_focus_obj       = lv_obj_get_child(list,0);
                            get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                            lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                            }
                        else {
                            get_focus_obj       = lv_obj_get_child(list,0);
                            p_cur_node          = lv_obj_get_user_data(get_focus_obj);
                            p_cur_node          = (phonebook_map_node_t *) get_phonebook_prev_node(p_cur_node);
                            ui_screen_phone_list_create(p_screen_param,p_screen_param->obj_list,p_cur_node);

                            if (p_screen_param->list_first_index > 0)
                                p_screen_param->list_first_index--;

                            pre_focus_obj       = lv_obj_get_child(list,1);
                            get_focus_obj       = lv_obj_get_child(list,0);
                            lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                            child_cnt           = lv_obj_get_child_cnt(list);

                            }
                        }

                    //label = lv_obj_get_child(pre_focus_obj, 0);
                    //lv_label_set_long_mode(label ,LV_LABEL_LONG_CLIP);
                    label               = lv_obj_get_child(get_focus_obj,0);

                    //lv_label_set_long_mode(label ,LV_LABEL_LONG_SCROLL); 
                    child_id            = get_list_child_focused_id(list,child_cnt);

                    uint32_t        per =
                         (p_screen_param->list_first_index + child_id) * (100) / (p_screen_param->find_count - 1);

                    per                 = per * (100 - p_screen_param->bar_high) / 100;
                    per                 = 100 - per;

                    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
                    lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
                    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);


                    app_fp_play_tts_phonebook(lv_label_get_text(label));
                    }
                break;

            case LV_KEY_DOWN:
                {
                    if (child_cnt <= 1)
                        return;

                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    if (child_id != child_cnt - 1) {
                        get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    else {
                        phonebook_map_node_t * p_cur_node;

                        get_focus_obj       = lv_obj_get_child(list,child_id);
                        p_cur_node          = lv_obj_get_user_data(get_focus_obj);

                        if (p_cur_node == get_phonebook_tail_node_find(p_screen_param)) {
                            p_cur_node          = get_phonebook_head_node_find(p_screen_param);
                            ui_screen_phone_list_create(p_screen_param,p_screen_param->obj_list,p_cur_node);
                            p_screen_param->list_first_index = 0;

                            pre_focus_obj       = lv_obj_get_child(list,1);
                            get_focus_obj       = lv_obj_get_child(list,0);
                            lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                            child_cnt           = lv_obj_get_child_cnt(list);
                            }
                        else {
                            get_focus_obj       = lv_obj_get_child(list,1);
                            p_cur_node          = lv_obj_get_user_data(get_focus_obj);
                            ui_screen_phone_list_create(p_screen_param,p_screen_param->obj_list,p_cur_node);

                            if (p_screen_param->list_first_index < p_screen_param->find_count)
                                p_screen_param->list_first_index++;

                            child_cnt           = lv_obj_get_child_cnt(list);
                            pre_focus_obj       = lv_obj_get_child(list,child_cnt - 2);
                            get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                            lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                            }
                        }

                    //label = lv_obj_get_child(pre_focus_obj, 0);
                    //lv_label_set_long_mode(label ,LV_LABEL_LONG_CLIP);
                    label               = lv_obj_get_child(get_focus_obj,0);

                    //lv_label_set_long_mode(label ,LV_LABEL_LONG_SCROLL); 
                    child_id            = get_list_child_focused_id(list,child_cnt);

                    uint32_t        per =
                         (p_screen_param->list_first_index + child_id) * (100) / (p_screen_param->find_count - 1);

                    per                 = per * (100 - p_screen_param->bar_high) / 100;
                    per                 = 100 - per;

                    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
                    lv_bar_set_start_value(p_screen_param->bar,per - p_screen_param->bar_high,LV_ANIM_OFF);
                    lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);



                    app_fp_play_tts_phonebook(lv_label_get_text(label));

                    }
                break;

#endif

            case APP_KEY_VALUE_TOP_LEFT:
                {
                    alv_am_win_exit_current(NULL);
                    }
                break;

            case APP_KEY_VALUE_TOP_RIGHT:
                if (p_screen_param->wirte_count) {
                    lv_textarea_del_char(p_screen_param->obj_textarea);

                    label               = lv_textarea_get_label(p_screen_param->obj_textarea);
                    count               = _lv_txt_get_encoded_length(lv_label_get_text(label));

                    if (p_screen_param->wirte_count != count) {
                        if (count != 0) {
#ifdef UI_DISPLAY_SPEED
                            p_screen_param->p_start_node = (phonebook_map_node_t *) get_phonebook_head_node();
                            p_screen_param->p_end_node = (phonebook_map_node_t *) get_phonebook_tail_node();
                            phonebook_find_list_by_text(ui_Screen,lv_label_get_text(label));

#else

                            if (p_screen_param->obj_list_find) {
                                lv_obj_del(p_screen_param->obj_list_find);
                                p_screen_param->obj_list_find = NULL;
                                }

                            p_screen_param->obj_list_find = phonebook_find_list_by_text(ui_Screen,
                                p_screen_param->obj_list,lv_label_get_text(label));
                            lv_obj_add_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                            }
                        else {
#ifdef UI_DISPLAY_SPEED
                            ui_screen_phone_list_reset_create(p_screen_param);

#else

                            if (p_screen_param->obj_list_find) {
                                lv_obj_del(p_screen_param->obj_list_find);
                                p_screen_param->obj_list_find = NULL;
                                }

                            lv_obj_clear_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                            }

                        p_screen_param->wirte_count = count;
                        }
                    }
                else {
                    alv_am_win_exit_current(NULL);
                    }

                break;

            case LV_KEY_ENTER:
                {
                    if (list == NULL)
                        break;

                    get_focus_obj       = lv_obj_get_child(list,child_id);
                    ui_screen_phonebook_enter_param_t enter_param;

                    enter_param.p_cur_node = (phonebook_map_node_t *) lv_obj_get_user_data(get_focus_obj);

                    if (enter_param.p_cur_node == NULL)
                        break;

                    read_phonebook_param_storge(enter_param.p_cur_node,&enter_param.phonebook_param);

                    //alv_am_win_enter(NULL,"details",(void*)&enter_param);
                    alv_am_win_exit_action(NULL,"list_option",NULL);
                    alv_am_win_jump_action(NULL,"details",(void *) &enter_param);
                    }
                break;

            case LV_KEY_END:
                alv_am_app_exit_action_all();
                break;

            default:
                ime_pinyin_ui_event_actions(key,p_screen_param->pinyin);
                {

                    label               = lv_textarea_get_label(p_screen_param->obj_textarea);
                    count               = _lv_txt_get_encoded_length(lv_label_get_text(label));

                    if (p_screen_param->wirte_count != count) {
                        if (count != 0) {
#ifdef UI_DISPLAY_SPEED
                            phonebook_find_list_by_text(ui_Screen,lv_label_get_text(label));

#else

                            if (p_screen_param->obj_list_find) {
                                lv_obj_del(p_screen_param->obj_list_find);
                                p_screen_param->obj_list_find = NULL;
                                }

                            p_screen_param->obj_list_find = phonebook_find_list_by_text(ui_Screen,
                                p_screen_param->obj_list,lv_label_get_text(label));
                            lv_obj_add_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                            }
                        else {
#ifdef UI_DISPLAY_SPEED
                            ui_screen_phone_list_reset_create(p_screen_param);

#else

                            if (p_screen_param->obj_list_find) {
                                lv_obj_del(p_screen_param->obj_list_find);
                                p_screen_param->obj_list_find = NULL;
                                }

                            lv_obj_clear_flag(p_screen_param->obj_list,LV_OBJ_FLAG_HIDDEN);
#endif
                            }

                        p_screen_param->wirte_count = count;
                        }
                    }
                break;
            }
        }
}




